char **generatePossibleNextMoves(char *s, int *returnSize) {
  int n = strlen(s);
  char **res = (char **)malloc(sizeof(char *) * (n > 0 ? n : 1));
  *returnSize = 0;
  for (int i = 0; i < n - 1; i++) {
    if (s[i] == '+' && s[i + 1] == '+') {
      char *tmp = strdup(s);
      tmp[i] = '-';
      tmp[i + 1] = '-';
      res[(*returnSize)++] = tmp;
    }
  }
  return res;
}

class Solution {
public:
  vector<string> generatePossibleNextMoves(string s) {
    int n = s.size();
    vector<string> res;
    for (int i = 0; i < n - 1; i++) {
      if (s[i] == '+' && s[i + 1] == '+') {
        string tmp = s;
        tmp[i] = '-';
        tmp[i + 1] = '-';
        res.push_back(tmp);
      }
    }
    return res;
  }
};

func generatePossibleNextMoves(s string) []string {
	res := []string{}
	for i := 0; i+1 < len(s); i++ {
		if s[i] == '+' && s[i+1] == '+' {
			t := []byte(s)
			t[i], t[i+1] = '-', '-'
			res = append(res, string(t))
		}
	}
	return res
}

class Solution {
  public List<String> generatePossibleNextMoves(String s) {
    List<String> res = new ArrayList<>();
    for (int i = 0; i + 1 < s.length(); i++) {
      if (s.charAt(i) == '+' && s.charAt(i + 1) == '+') {
        char[] t = s.toCharArray();
        t[i] = '-';
        t[i + 1] = '-';
        res.add(new String(t));
      }
    }
    return res;
  }
}

class Solution:
    def generatePossibleNextMoves(self, s: str) -> List[str]:
        res = []
        for i in range(len(s) - 1):
            if s[i] == "+" and s[i + 1] == "+":
                res.append(s[:i] + "--" + s[i + 2:])
        return res

impl Solution {
  pub fn generate_possible_next_moves(s: String) -> Vec<String> {
    let b = s.as_bytes();
    let mut res = vec![];
    for i in 0..b.len().saturating_sub(1) {
      if b[i] == b'+' && b[i + 1] == b'+' {
        let mut t = b.to_vec();
        t[i] = b'-';
        t[i + 1] = b'-';
        res.push(String::from_utf8(t).unwrap());
      }
    }
    res
  }
}

const generatePossibleNextMoves = (s: string): string[] => {
  const res: string[] = [];
  for (let i = 0; i + 1 < s.length; i++) {
    if (s[i] === '+' && s[i + 1] === '+') {
      res.push(s.slice(0, i) + '--' + s.slice(i + 2));
    }
  }
  return res;
};
